const processedIds = new Set(); // In production, use a database

async function processMessage(message) {
  if (processedIds.has(message.messageId)) {
    console.log("Duplicate message, skipping:", message.messageId);
    return;
  }

  const order = JSON.parse(message.body);
  await chargeCustomer(order.customerId, order.total);
  processedIds.add(message.messageId);
  console.log("Processed:", message.messageId);
}

async function retryWithBackoff(fn, maxRetries = 3) {
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      const delay = Math.min(1000 * 2 ** attempt + Math.random() * 1000, 30000);
      console.log(`Attempt ${attempt + 1} failed, retrying in ${delay}ms`);
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }
  throw new Error("Max retries exceeded");
}

